def maxMinGap(positions, m):
    pos = sorted(positions)

    def can(d):
        placed, last = 1, pos[0]
        for x in pos[1:]:
            if x - last >= d:
                placed += 1
                last = x
                if placed >= m:
                    return True
        return placed >= m

    lo, hi = 1, (pos[-1] - pos[0]) // (m - 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
